// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile logFile;

    function setUp() public {
        c = new DEP_BANK();
        logFile = new LogFile();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        c.SetLogFile(address(logFile));
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));

        assertTrue(ok, "Deposit with a configured LogFile must succeed");
    }
}
